1	"use client";
2	
3	/**
4	 * FLAGSHIP — "Combined" greatest-hits game-server landing template.
5	 *
6	 * Curated merge of the three approved preview directions, composed into one
7	 * coherent premium page (NOT a stack of all three):
8	 *
9	 *   • from CINEMATIC — the full-bleed key-art hero with a navy-scrimmed
10	 *     asymmetric split + a genuinely-animated LIVE server panel (ticking player
11	 *     count, a drawn TPS graph, a streaming console) and slow scroll parallax;
12	 *     plus the plan cards and the blurred-art cinematic CTA.
13	 *   • from EDITORIAL — the numbered buying-reasons rail with the scroll-linked
14	 *     progress spine, beside a STICKY recommended plan card whose 47-second
15	 *     deploy ring counts up as it pins.
16	 *   • from COMMAND DECK — a HUD/console deploy beat: a glass terminal that types
17	 *     its boot sequence to "✓ online in 47s" next to animated telemetry gauges.
18	 *
19	 * Reuses the shared kit hooks/atoms + the scoped `pv-*` motion system so it
20	 * stays in the same design language. Everything respects prefers-reduced-motion.
21	 *
22	 * Net-new, PREVIEW-ONLY. Touches no live page or shared component.
23	 */
24	
25	import Link from "next/link";
26	import { useState } from "react";
27	import type { PreviewGame } from "./data";
28	import {
29	  usePrefersReducedMotion,
30	  useInViewOnce,
31	  useJitter,
32	  useCountUp,
33	  useParallax,
34	  useScrollProgress,
35	  useTypedLines,
36	  StarRow,
37	  ReasonIcon,
38	} from "./kit";
39	import { GameLogo } from "@/components/marketing/GameLogo";
40	import {
41	  IconBolt,
42	  IconShield,
43	  IconNvme,
44	  IconGlobe,
45	  IconUsers,
46	  IconClock,
47	  IconCheck,
48	  IconServer,
49	  IconGauge,
50	} from "@/components/marketing/icons";
51	import { recommendedSpecForPlayers, playerSliderMax } from "@/lib/game-player-recommend";
52	
53	/* ── Live TPS sparkline — draws on view, pulsing playhead (from Cinematic) ── */
54	function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
55	  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
56	  const w = 220;
57	  const h = 46;
58	  const min = 19.5;
59	  const max = 20.2;
60	  const step = w / (pts.length - 1);
61	  const coords = pts.map((v, i) => {
62	    const x = i * step;
63	    const y = h - ((v - min) / (max - min)) * h;
64	    return [x, y] as const;
65	  });
66	  const line = coords.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
67	  const area = `${line} L${w} ${h} L0 ${h} Z`;
68	  const [ex, ey] = coords[coords.length - 1];
69	  return (
70	    <svg viewBox={`0 0 ${w} ${h}`} className="h-[46px] w-full" preserveAspectRatio="none" aria-hidden>
71	      <defs>
72	        <linearGradient id="pv-cmb-tps-fill" x1="0" y1="0" x2="0" y2="1">
73	          <stop offset="0%" stopColor={accent} stopOpacity="0.35" />
74	          <stop offset="100%" stopColor={accent} stopOpacity="0" />
75	        </linearGradient>
76	      </defs>
77	      <path d={area} fill="url(#pv-cmb-tps-fill)" />
78	      <path
79	        d={line}
80	        fill="none"
81	        stroke={accent}
82	        strokeWidth="1.6"
83	        strokeLinecap="round"
84	        strokeLinejoin="round"
85	        className={reduced || !active ? "" : "pv-draw"}
86	      />
87	      <circle cx={ex} cy={ey} r="3" fill={accent} className={reduced ? "" : "motion-safe:animate-pulse-dot"} />
88	    </svg>
89	  );
90	}
91	
92	/* ── Floating LIVE control panel — hero right column (from Cinematic) ──────── */
93	function LiveOpsPanel({ game }: { game: PreviewGame }) {
94	  const reduced = usePrefersReducedMotion();
95	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
96	  const totalSlots = 60;
97	  const players = useJitter(47, 3, seen, 2400, reduced);
98	  const filled = Math.min(totalSlots, players);
99	  const cpu = useCountUp(38, seen, 1200, reduced);
100	  const ping = useJitter(12, 2, seen, 3000, reduced);
101	
102	  const logLines = [
103	    { t: "player connected · s.singe", c: "text-emerald-300" },
104	    { t: "player connected · DevReez", c: "text-emerald-300" },
105	    { t: "[Oxide] loaded 14 plugins", c: "text-slate-400" },
106	    { t: "map saved (0.4s) · autobackup ok", c: "text-slate-500" },
107	  ];
108	
109	  return (
110	    <div ref={ref} className={reduced ? "" : "pv-float"}>
111	      <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/85 shadow-2xl shadow-black/50 backdrop-blur-xl">
112	        <div
113	          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
114	          style={{ background: `radial-gradient(45% 45% at 80% 0%, ${game.accent}33, transparent 70%)` }}
115	          aria-hidden
116	        />
117	        {/* header */}
118	        <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
119	          <GameLogo family={game.family} size={22} />
120	          <span className="ml-0.5 truncate text-[11px] font-medium text-slate-300">{game.worldName}</span>
121	          <span className="ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
122	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
123	            running
124	          </span>
125	        </div>
126	
127	        <div className="space-y-4 p-4">
128	          {/* live stat row */}
129	          <div className="grid grid-cols-3 gap-2.5">
130	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
131	              <p className="text-[10px] uppercase tracking-wide text-slate-500">Players</p>
132	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
133	                {filled}
134	                <span className="text-sm text-slate-500">/{totalSlots}</span>
135	              </p>
136	            </div>
137	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
138	              <p className="text-[10px] uppercase tracking-wide text-slate-500">Ping</p>
139	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
140	                {ping}
141	                <span className="text-sm text-slate-500"> ms</span>
142	              </p>
143	            </div>
144	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
145	              <p className="text-[10px] uppercase tracking-wide text-slate-500">CPU</p>
146	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
147	                {cpu}
148	                <span className="text-sm text-slate-500">%</span>
149	              </p>
150	            </div>
151	          </div>
152	
153	          {/* TPS graph */}
154	          <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3.5 pb-2 pt-3">
155	            <div className="flex items-center justify-between">
156	              <p className="text-[11px] font-medium text-slate-400">Server TPS · last 60s</p>
157	              <p className="font-mono text-[11px] font-semibold" style={{ color: game.accent }}>
158	                20.0
159	              </p>
160	            </div>
161	            <div className="mt-1">
162	              <TpsGraph accent={game.accent} active={seen} reduced={reduced} />
163	            </div>
164	          </div>
165	
166	          {/* player slots */}
167	          <div>
168	            <div className="mb-2 flex items-center justify-between text-[11px]">
169	              <span className="text-slate-400">Player slots</span>
170	              <span className="font-mono text-slate-500">{filled} online</span>
171	            </div>
172	            <div className="grid grid-cols-12 gap-1">
173	              {Array.from({ length: totalSlots }).map((_, i) => (
174	                <span
175	                  key={i}
176	                  className={`h-2.5 origin-bottom rounded-[3px] ${reduced ? "" : "motion-safe:animate-grow-up"} ${
177	                    i < filled ? "" : "border border-white/10 bg-white/[0.03]"
178	                  }`}
179	                  style={
180	                    i < filled
181	                      ? { background: `linear-gradient(to top, ${game.accent}, #3b82f6)`, animationDelay: `${i * 14}ms` }
182	                      : undefined
183	                  }
184	                />
185	              ))}
186	            </div>
187	          </div>
188	
189	          {/* streaming console */}
190	          <div className="rounded-xl border border-white/[0.06] bg-black/40 p-3 font-mono text-[11px] leading-relaxed">
191	            {logLines.map((l, i) => (
192	              <div
193	                key={i}
194	                className={`${l.c} ${reduced ? "" : "motion-safe:animate-line-in"}`}
195	                style={{ animationDelay: `${300 + i * 260}ms` }}
196	              >
197	                {l.t}
198	              </div>
199	            ))}
200	            <div className="mt-0.5 flex items-center text-slate-500">
201	              <span className="text-emerald-400">&gt;&nbsp;</span>
202	              <span className="inline-block h-3 w-1.5 bg-slate-400 motion-safe:animate-blink" />
203	            </div>
204	          </div>
205	        </div>
206	      </div>
207	    </div>
208	  );
209	}
210	
211	/* ── 47-second deploy ring — counts up + fills on view (from Editorial) ───── */
212	function DeployRing({ accent }: { accent: string }) {
213	  const reduced = usePrefersReducedMotion();
214	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
215	  const val = useCountUp(47, seen, 1300, reduced);
216	  const r = 34;
217	  const c = 2 * Math.PI * r;
218	  const offset = c * (1 - Math.min(1, val / 47));
219	  return (
220	    <div ref={ref} className="flex items-center gap-4">
221	      <div className="relative h-[92px] w-[92px] shrink-0">
222	        <svg viewBox="0 0 92 92" className="h-full w-full -rotate-90">
223	          <circle cx="46" cy="46" r={r} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="6" />
224	          <circle
225	            cx="46"
226	            cy="46"
227	            r={r}
228	            fill="none"
229	            stroke={accent}
230	            strokeWidth="6"
231	            strokeLinecap="round"
232	            strokeDasharray={c}
233	            strokeDashoffset={offset}
234	          />
235	        </svg>
236	        <div className="absolute inset-0 flex flex-col items-center justify-center">
237	          <span className="font-mono text-2xl font-bold tabular-nums text-white">{val}</span>
238	          <span className="text-[10px] font-medium uppercase tracking-wide text-slate-500">sec</span>
239	        </div>
240	      </div>
241	      <div>
242	        <p className="text-sm font-semibold text-white">Live in 47 seconds</p>
243	        <p className="mt-1 text-xs leading-relaxed text-slate-400">
244	          From checkout to a running, connect-ready server — measured, not marketing.
245	        </p>
246	      </div>
247	    </div>
248	  );
249	}
