251	/* ── animated telemetry gauge (from Command Deck) ─────────────────────────── */
252	function Gauge({
253	  label,
254	  value,
255	  suffix,
256	  pct,
257	  accent,
258	  active,
259	  reduced,
260	  delay,
261	}: {
262	  label: string;
263	  value: number | string;
264	  suffix?: string;
265	  pct: number;
266	  accent: string;
267	  active: boolean;
268	  reduced: boolean;
269	  delay: number;
270	}) {
271	  return (
272	    <div>
273	      <div className="mb-1.5 flex items-baseline justify-between">
274	        <span className="text-[11px] font-medium uppercase tracking-wide text-slate-400">{label}</span>
275	        <span className="font-mono text-sm font-semibold tabular-nums text-white">
276	          {value}
277	          {suffix && <span className="text-slate-500">{suffix}</span>}
278	        </span>
279	      </div>
280	      <div className="h-2 w-full overflow-hidden rounded-full bg-white/[0.06]">
281	        <div
282	          className={`h-full origin-left rounded-full ${reduced || !active ? "" : "motion-safe:animate-grow-x"}`}
283	          style={{
284	            width: `${pct}%`,
285	            background: `linear-gradient(90deg, #3b82f6, ${accent})`,
286	            animationDelay: `${delay}ms`,
287	          }}
288	        />
289	      </div>
290	    </div>
291	  );
292	}
