294	/* ── HUD deploy beat — typing terminal + telemetry gauges (from Command Deck) */
295	function DeployBeat({ game }: { game: PreviewGame }) {
296	  const reduced = usePrefersReducedMotion();
297	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
298	  const players = useJitter(47, 3, seen, 2500, reduced);
299	  const cpu = useJitter(38, 4, seen, 2200, reduced);
300	  const ram = useJitter(61, 3, seen, 2800, reduced);
301	  const { done, current, caret } = useTypedLines(game.boot, seen, reduced);
302	  const totalSlots = 60;
303	
304	  return (
305	    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
306	      <div
307	        className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#070c17]/90 backdrop-blur-xl"
308	        style={{ boxShadow: `0 40px 120px -50px ${game.accent}80, 0 0 0 1px rgba(255,255,255,0.04)` }}
309	      >
310	        {/* drifting grid backdrop */}
311	        <div
312	          className={`pointer-events-none absolute inset-0 opacity-[0.5] ${reduced ? "" : "pv-grid-pan"}`}
313	          style={{
314	            backgroundImage:
315	              "linear-gradient(rgba(255,255,255,0.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px)",
316	            backgroundSize: "40px 40px",
317	          }}
318	          aria-hidden
319	        />
320	        <div
321	          className="pointer-events-none absolute -inset-24 opacity-70"
322	          style={{ background: `radial-gradient(40% 40% at 85% 0%, ${game.accent}30, transparent 70%)` }}
323	          aria-hidden
324	        />
325	
326	        {/* deck header */}
327	        <div className="relative flex items-center gap-3 border-b border-white/[0.07] bg-white/[0.02] px-5 py-3">
328	          <GameLogo family={game.family} size={26} />
329	          <span className="text-sm font-semibold text-white">{game.worldName}</span>
330	          <span className="hidden font-mono text-[11px] text-slate-500 sm:inline">{game.region}</span>
331	          <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
332	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
333	            live
334	          </span>
335	        </div>
336	
337	        <div className="relative grid gap-4 p-4 lg:grid-cols-5 lg:p-5">
338	          {/* deploy terminal — HUD framed, types boot sequence */}
339	          <div className="lg:col-span-3">
340	            <div className="relative h-full overflow-hidden rounded-2xl border border-white/10 bg-black/55 p-4 pt-5 font-mono text-[12px] leading-relaxed">
341	              {/* scan line */}
342	              {!reduced && (
343	                <div
344	                  className="pv-scan pointer-events-none absolute inset-x-0 top-0 h-16"
345	                  style={{ background: `linear-gradient(to bottom, ${game.accent}00, ${game.accent}1f, ${game.accent}00)` }}
346	                  aria-hidden
347	                />
348	              )}
349	              {/* corner brackets */}
350	              {["left-2.5 top-2.5 border-l-2 border-t-2", "right-2.5 top-2.5 border-r-2 border-t-2", "left-2.5 bottom-2.5 border-l-2 border-b-2", "right-2.5 bottom-2.5 border-r-2 border-b-2"].map(
351	                (pos) => (
352	                  <span key={pos} className={`absolute h-5 w-5 rounded-[3px] ${pos}`} style={{ borderColor: `${game.accent}aa` }} aria-hidden />
353	                ),
354	              )}
355	              <div className="mb-3 flex items-center gap-1.5">
356	                <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
357	                <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
358	                <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
359	                <span className="ml-2 text-[10px] uppercase tracking-wider text-slate-500">deploy · {game.name.toLowerCase()}</span>
360	              </div>
361	              <div className="relative">
362	                {done.map((l, i) => {
363	                  const ok = l.startsWith("✓");
364	                  return (
365	                    <div key={i} className={ok ? "font-semibold" : "text-slate-400"} style={ok ? { color: game.accent } : undefined}>
366	                      {l}
367	                    </div>
368	                  );
369	                })}
370	                {caret < game.boot.length && (
371	                  <div className="text-slate-300">
372	                    {current}
373	                    <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-slate-300 motion-safe:animate-blink" />
374	                  </div>
375	                )}
376	              </div>
377	            </div>
378	          </div>
379	
380	          {/* telemetry gauges rail */}
381	          <div className="flex flex-col gap-4 lg:col-span-2">
382	            <div className="relative rounded-2xl border border-white/[0.07] bg-white/[0.02] p-4">
383	              <p className="mb-4 text-[11px] font-semibold uppercase tracking-wider text-slate-500">Live telemetry</p>
384	              <div className="space-y-4">
385	                <Gauge label="Players" value={players} suffix={`/${totalSlots}`} pct={(players / totalSlots) * 100} accent={game.accent} active={seen} reduced={reduced} delay={80} />
386	                <Gauge label="CPU" value={cpu} suffix="%" pct={cpu} accent={game.accent} active={seen} reduced={reduced} delay={160} />
387	                <Gauge label="Memory" value={ram} suffix="%" pct={ram} accent={game.accent} active={seen} reduced={reduced} delay={240} />
388	                <Gauge label="TPS" value="20.0" pct={100} accent={game.accent} active={seen} reduced={reduced} delay={320} />
389	              </div>
390	            </div>
391	            <div className="flex items-center justify-between rounded-2xl border border-white/[0.07] bg-white/[0.02] px-4 py-3 text-[11px] text-slate-400">
392	              <span className="font-mono">uptime 4d 06h</span>
393	              <span className="inline-flex items-center gap-1.5 text-emerald-300">
394	                <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" /> healthy
395	              </span>
396	            </div>
397	          </div>
398	        </div>
399	      </div>
400	    </div>
