404	/* ── numbered reason row on the scroll spine (from Editorial) ─────────────── */
405	function ReasonRow({ game, r, delay }: { game: PreviewGame; r: PreviewGame["reasons"][number]; delay: number }) {
406	  const { ref, seen } = useInViewOnce<HTMLLIElement>();
407	  return (
408	    <li
409	      ref={ref}
410	      className={`relative transition-all duration-700 ease-out ${seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"}`}
411	      style={{ transitionDelay: `${delay}ms` }}
412	    >
413	      <span
414	        className="absolute -left-[26px] top-1.5 h-3 w-3 rounded-full ring-4 ring-navy-950"
415	        style={{ background: game.accent }}
416	        aria-hidden
417	      />
418	      <div className="flex items-baseline gap-4">
419	        <span className="font-mono text-3xl font-bold tabular-nums" style={{ color: game.accent }}>
420	          {r.n}
421	        </span>
422	        <div>
423	          <h3 className="flex items-center gap-2.5 text-xl font-semibold text-white">
424	            <span style={{ color: game.accent }} className="opacity-90">
425	              <ReasonIcon icon={r.icon} size={18} />
426	            </span>
427	            {r.title}
428	          </h3>
429	          <p className="mt-2 max-w-lg text-[15px] leading-relaxed text-slate-400">{r.body}</p>
430	        </div>
431	      </div>
432	    </li>
433	  );
434	}
435	
436	/* ── Interactive pricing configurator ─────────────────────────────────────────
437	 * Drag the player count and the recommended plan + price update live. The
438	 * recommended RAM/vCPU/NVMe readout is GROUNDED in the real fitted player→resource
439	 * curve (lib/game-player-recommend — the same math the live GameDeployWizard uses),
440	 * and the plan match is driven by each plan's advertised slot capacity (falling
441	 * back to the RAM curve for VPS-style, slot-less plans). We reuse that recommend
442	 * logic rather than the DB-shaped <GameConfigurator/> because this preview runs on
443	 * PreviewGame data, not db.gamePlan rows — but the interaction language (player
444	 * control + brand-accented tiers) matches the site's GameConfigurator. */
445	function ramGbOf(ram: string) {
446	  return parseFloat(ram) || 0;
447	}
448	function gbLabel(mb: number) {
449	  const v = mb / 1024;
450	  return `${v.toFixed(v % 1 ? 1 : 0)} GB`;
451	}
452	
453	function PlanConfigurator({ game }: { game: PreviewGame }) {
454	  const reduced = usePrefersReducedMotion();
455	  const plans = game.plans;
456	
457	  const slotVals = plans.map((p) => p.slots).filter((s): s is number => s != null);
458	  const anySlots = slotVals.length > 0;
459	  const topSlots = anySlots ? Math.max(...slotVals) : null;
460	
461	  // Slider spans the plan ladder with ~30% headroom (to show "past our tiers"),
462	  // capped by the recommend module's own per-family ceiling.
463	  const sliderMax = topSlots
464	    ? Math.min(playerSliderMax(game.family), Math.max(topSlots + 16, Math.round(topSlots * 1.3)))
465	    : 64;
466	
467	  const popular = plans.find((p) => p.popular);
468	  const [players, setPlayers] = useState(popular?.slots ?? topSlots ?? Math.round(sliderMax / 2));
469	
470	  const spec = recommendedSpecForPlayers(game.family, players);
471	  const recRamGB = spec.ramMB / 1024;
472	
473	  const matchIdx = (() => {
474	    if (anySlots) {
475	      const i = plans.findIndex((p) => p.slots != null && p.slots >= players);
476	      return i === -1 ? plans.length - 1 : i;
477	    }
478	    const i = plans.findIndex((p) => ramGbOf(p.ram) >= recRamGB);
479	    return i === -1 ? plans.length - 1 : i;
480	  })();
481	  const matched = plans[matchIdx];
482	  const beyondTop = topSlots != null && players > topSlots;
483	
