import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, second pilot page.
 *
 * The previous live page's 16 GB plan was $27.99/mo, but the PREVIEW_GAMES.palworld
 * demo data had it at $24.99 (illustrative, never wired to real billing). That's the
 * one real price this page charges, so it's corrected here rather than trusting the
 * preview figure — every other field (art, accent/glow, boot lines, reasons,
 * kicker/headline/deck) is the real preview copy, unchanged.
 *
 * FAQ + guides + related sections are carried over verbatim from the previous page
 * (same copy, same JSON-LD) since GameLandingCombined doesn't render those itself.
 */

export const metadata: Metadata = {
  title: "Palworld VPS Server Hosting — Up to 32 Players, Instant Setup",
  description:
    "Palworld server hosting from $14.99/mo. Full 32-player dedicated servers, auto-restarts for the memory leak, full file access and instant setup on a low-latency network.",
  alternates: { canonical: "/palworld-server-hosting" },
  openGraph: {
    type: "article",
    title: "Palworld VPS Server Hosting — Up to 32 Players, Instant Setup",
    description:
      "Managed Palworld hosting: 32-player servers, scheduled auto-restarts, full file access and instant setup. From $14.99/mo.",
    url: `${APP_URL}/palworld-server-hosting`,
  },
};

// Real live price differs from the PREVIEW_GAMES.palworld demo figure — see the
// file-header comment. Every other field is the real preview copy, unchanged.
const GAME = {
  ...PREVIEW_GAMES.palworld,
  plans: PREVIEW_GAMES.palworld.plans.map((p) => (p.id === "pal-16" ? { ...p, price: "$27.99" } : p)),
};

const FAQ = [
  {
    q: "How much RAM do I need for a Palworld server?",
    a: "Plan for 16 GB as your practical baseline. Palworld is heavy: a fresh co-op world idles fine on 8 GB, but a busy 32-player server with lots of built bases climbs toward 24–32 GB over time. Our 16 GB / 32-player plan is the recommended pick for a full server, and you can scale up whenever your world grows.",
  },
  {
    q: "How many players can a Palworld server hold?",
    a: "Palworld's dedicated server caps at 32 players. Our 16 GB plan is sized for a full 32-slot server; the 8 GB plan suits a smaller co-op group.",
  },
  {
    q: "What port does Palworld use?",
    a: "Palworld uses UDP port 8211 by default. On a managed Nxeon server the port is opened and the connect string is handed to you automatically — nothing to forward.",
  },
  {
    q: "My Palworld server's RAM keeps climbing — is that normal?",
    a: "Yes. Palworld has a well-known memory leak where RAM usage grows the longer the server runs, especially with large bases. The standard fix is a scheduled restart every 6–12 hours to reclaim memory, which you can automate from the panel so players never notice.",
  },
  {
    q: "Can I add mods and change server settings?",
    a: "Yes. You get full file access to edit PalWorldSettings.ini — day/night length, capture rates, difficulty, XP multipliers — and to drop in mods. Changes apply on the next restart.",
  },
  {
    q: "Is Palworld hosting a VPS?",
    a: "Yes — every Palworld server here runs on a dedicated VPS with its own guaranteed CPU, RAM and NVMe storage, plus full file and SFTP access. You get the raw power and control of a VPS, but we handle the SteamCMD install, port setup, patch-day updates and auto-restarts for you, so you skip the manual server administration.",
  },
];

const GUIDES = [
  { label: "How to set up a Palworld dedicated server on a VPS", href: "/blog/how-to-set-up-a-palworld-dedicated-server-on-a-vps" },
  { label: "Palworld dedicated server requirements: RAM and CPU", href: "/blog/palworld-dedicated-server-requirements-ram-and-cpu" },
  { label: "How to configure a Palworld server: settings explained", href: "/blog/how-to-configure-a-palworld-server-settings-explained" },
  { label: "Best VPS specs for a Palworld server", href: "/blog/best-vps-specs-for-a-palworld-server" },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "Valheim server hosting", href: "/valheim-server-hosting" },
  { label: "ARK server hosting", href: "/ark-server-hosting" },
